def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc),
                               (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w
                            and grid[nr][nc] == 5
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            min_r = min(x for x, _ in cells)
            max_r = max(x for x, _ in cells)
            min_c = min(y for _, y in cells)
            max_c = max(y for _, y in cells)

            gaps = [cc for cc in range(min_c, max_c + 1)
                    if grid[min_r][cc] == 0]
            for rr in range(min_r + 1, max_r):
                for cc in range(min_c + 1, max_c):
                    if out[rr][cc] == 0:
                        out[rr][cc] = 2

            for cc in gaps:
                out[min_r][cc] = 2

            if gaps and min_r > 0:
                for cc in range(min(gaps) + 1):
                    if out[min_r - 1][cc] == 0:
                        out[min_r - 1][cc] = 2

    return out
